export function isSpeculativeOrAiFuture(item: {
  title?: string | null;
  excerpt?: string | null;
  source_name?: string | null;
}): boolean {
  const text = itemText(item);
  if (CYBER_AI_KEEP_KEYWORDS.some(kw => text.includes(kw))) return false;

  if (/\bpros and cons\b|\badvantages and disadvantages\b|\bbenefits and (drawbacks|risks)\b/.test(text)) {
    return true;
  }
  if (/\bfuture of (ai|artificial intelligence|generative ai|machine learning|llm)\b/.test(text)) {
    return true;
  }
  if (/\b(ai|artificial intelligence|generative ai|llm)\b.{0,40}\b(predict|forecast|outlook|trend)\b/.test(text)) {
    return true;
  }
  if (/\b(predict|forecast|outlook)\b.{0,40}\b(ai|artificial intelligence|generative ai|llm)\b/.test(text)) {
    return true;
  }
  return SPECULATIVE_KEYWORDS.some(kw => text.includes(kw));
}

export function isStockRelated(item: { title?: string | null; excerpt?: string | null; source_name?: string | null }): boolean {
  const text = itemText(item);
  const src = (item.source_name ?? "").toLowerCase();
  if (/marketwatch|yahoo finance|seeking alpha|motley fool|cnbc|bloomberg markets|financial times/.test(src)) {
    return true;
  }
  if (/\bstock\b|\bstocks\b|\bshares\b|\bearnings\b|\bnyse\b|\bnasdaq\b|\bipo\b/.test(text)) {
    return true;
  }
  return STOCK_KEYWORDS.some(kw => text.includes(kw));
}

export function isIocDumpTitle(title: string | null | undefined): boolean {
  const t = (title ?? "").toLowerCase().trim();
  return IOC_TITLE_PREFIXES.some(p => t.startsWith(p));
}

export function isHiddenSource(name: string | null | undefined): boolean {
  if (!name) return false;
  const n = name.toLowerCase().trim();
  if (SUPPLY_CHAIN_VISIBLE_SOURCES.some(p => n.includes(p))) return false;
  return HIDDEN_SOURCE_PATTERNS.some(p => n.includes(p));
}

export function isPrioritySource(name: string | null | undefined): boolean {
  if (!name) return false;
  const n = name.toLowerCase().trim();
  return PRIORITY_SOURCES.some(p => n.includes(p));
}

export function hasNonCyberContent(item: { title?: string | null; excerpt?: string | null }): boolean {
  const text = itemText(item);
  return NON_CYBER_KEYWORDS.some(kw => text.includes(kw));
}

export function isCyberRelated(item: { source_name?: string | null; title?: string | null; category?: string | null; excerpt?: string | null }): boolean {
  if (hasNonCyberContent(item)) return false;

  const title    = (item.title    ?? "").toLowerCase();
  const category = (item.category ?? "").toLowerCase();
  const excerpt  = (item.excerpt  ?? "").toLowerCase();
  const combined = `${title} ${excerpt}`;

  if (/threat|malware|ransomware|breach|vulnerab|cve|exploit|incident|cyber|supply|cloud-security/.test(category)) {
    return true;
  }

  if (CYBERSEC_KEYWORDS.some(kw => combined.includes(kw))) return true;

  // Hacker News: only show security-relevant posts
  const src = (item.source_name ?? "").toLowerCase();
  if (/hacker.?news|hackernews/.test(src)) {
    const strong = [
      "ransomware", "malware", "cve-", "phishing", "breach", "exploit", "vulnerab",
      "cyber", "threat", "security", "kernel flaw", "zero-day", "zero day",
      "npm", "backdoor", "compromised", "hacked", "ddos", "botnet", "apt",
      "supply chain", "root access", "rce", "patch",
    ];
    return strong.some(kw => combined.includes(kw));
  }

  const strongOnly = ["ransomware", "malware", "cve-", "phishing", "breach", "exploit"];
  return strongOnly.some(kw => excerpt.includes(kw));
}

