export function isSupplyChainItem(item: {
  title?: string | null;
  excerpt?: string | null;
  category?: string | null;
  source_name?: string | null;
}): boolean {
  const cat = (item.category ?? "").toLowerCase();
  if (cat === "supply-chain" || cat.includes("supply")) return true;
  const src = (item.source_name ?? "").toLowerCase();
  if (SUPPLY_CHAIN_VISIBLE_SOURCES.some(p => src.includes(p))) return true;
  const text = itemText(item);
  return SUPPLY_CHAIN_KW.some(kw => text.includes(kw));
}

export const MAX_FEED_AGE_DAYS = 15;

export function isWithinFeedAgeWindow(
  item: { fetched_at?: string | null; published_at?: string | null; created_at?: string | null },
  days = MAX_FEED_AGE_DAYS,
): boolean {
  const ts = item.fetched_at || item.published_at || item.created_at;
  if (!ts) return false;
  return Date.now() - new Date(ts).getTime() <= days * 86_400_000;
}

export function shouldShowFeedItem(
  item: { source_name?: string | null; title?: string | null; category?: string | null; excerpt?: string | null; fetched_at?: string | null; published_at?: string | null; created_at?: string | null },
): boolean {
  if (!isWithinFeedAgeWindow(item)) return false;
  if (isHiddenSource(item.source_name)) return false;
  if (isIocDumpTitle(item.title)) return false;
  if (isStockRelated(item)) return false;
  if (isSpeculativeOrAiFuture(item)) return false;
  return isCyberRelated(item);
}

export function filterFeedItems<T extends { source_name?: string | null; title?: string | null; category?: string | null; excerpt?: string | null }>(
  items: T[],
): T[] {
  return items.filter(item => shouldShowFeedItem(item));
}

/** Best timestamp for "most recently updated" ordering (ingest time beats publish time). */
export function itemRecencyMs(item: {
  fetched_at?: string | null;
  published_at?: string | null;
  created_at?: string | null;
}): number {
  return new Date(item.fetched_at || item.published_at || item.created_at || 0).getTime();
}

export function itemRecencyDate(item: {
  fetched_at?: string | null;
  published_at?: string | null;
  created_at?: string | null;
}): string {
  return item.fetched_at || item.published_at || item.created_at || "";
}

/** User-facing story age — prefer original publish time over ingest time. */
export function itemDisplayDate(item: {
  fetched_at?: string | null;
  published_at?: string | null;
  created_at?: string | null;
}): string {
  return item.published_at || item.fetched_at || item.created_at || "";
}

export function sortByRecency<T extends {
  fetched_at?: string | null;
  published_at?: string | null;
  created_at?: string | null;
}>(items: T[]): T[] {
  return [...items].sort((a, b) => itemRecencyMs(b) - itemRecencyMs(a));
}

/** Priority boost only for stories published in the last 3 days — avoids week-old CISA KEV rows burying today's news. */
const PRIORITY_BOOST_MAX_AGE_MS = 3 * 24 * 60 * 60 * 1000;

function prioritySortRank(item: {
  source_name?: string | null;
  fetched_at?: string | null;
  published_at?: string | null;
  created_at?: string | null;
}): number {
  if (!isPrioritySource(item.source_name)) return 1;
  const publishedMs = new Date(item.published_at || item.fetched_at || item.created_at || 0).getTime();
  if (!publishedMs || Date.now() - publishedMs > PRIORITY_BOOST_MAX_AGE_MS) return 1;
  return 0;
}

/** Priority CTI sources first (recent only), then newest ingested within each group. */
export function sortByPriorityThenRecency<T extends {
  source_name?: string | null;
  fetched_at?: string | null;
  published_at?: string | null;
  created_at?: string | null;
}>(items: T[]): T[] {
  return [...items].sort((a, b) => {
    const pa = prioritySortRank(a);
    const pb = prioritySortRank(b);
    if (pa !== pb) return pa - pb;
    return itemRecencyMs(b) - itemRecencyMs(a);
  });
}

